D=r'\frac{\text{d}y}{\text{d}x}'
def probe(r):
 f=r['question'][':question/answer-fields'][0];opts=[a for a in f[':answer-field/choices'] if '\\frac' not in a[':answer/value'].replace(D,'D')]
 return len(opts)==1 and opts[0][':answer/id']==f[':answer-field/correct'][1]
